// Lê o evento da Evolution API e normaliza a mensagem.
// Ignora: mensagens enviadas pelo próprio NESTOR, grupos, status, reações.
const raw = $input.first().json;
const body = raw.body || raw;

const evento = String(body.event || '').toLowerCase().replace('_', '.');
if (evento && evento !== 'messages.upsert') return [];

const d = Array.isArray(body.data) ? body.data[0] : body.data;
if (!d || !d.key || d.key.fromMe) return [];

let jid = d.key.remoteJid || '';
if (jid.endsWith('@g.us') || jid === 'status@broadcast') return [];
// Contas novas do WhatsApp chegam como @lid; o número real vem em senderPn/remoteJidAlt
if (jid.endsWith('@lid')) jid = d.key.senderPn || d.key.remoteJidAlt || jid;
const phone = jid.split('@')[0].split(':')[0];

function unwrap(m) {
  let x = m || {};
  for (let i = 0; i < 5; i++) {
    const w = x.ephemeralMessage || x.viewOnceMessage || x.viewOnceMessageV2 ||
              x.viewOnceMessageV2Extension || x.documentWithCaptionMessage;
    if (!w || !w.message) break;
    x = w.message;
  }
  return x;
}

function midiaDe(m) {
  if (m.imageMessage) return { tipo: 'imagem', node: m.imageMessage };
  if (m.videoMessage) return { tipo: 'video', node: m.videoMessage };
  if (m.documentMessage) return { tipo: 'documento', node: m.documentMessage };
  if (m.audioMessage) return { tipo: m.audioMessage.ptt ? 'voz' : 'audio', node: m.audioMessage };
  return null;
}

function tamanhoDe(v) {
  if (v == null) return null;
  if (typeof v === 'object') return Number(v.low || 0);
  return Number(v) || null;
}

const msg = unwrap(d.message);
let texto = msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '';
let midia = midiaDe(msg);
let mediaKey = { key: d.key, message: d.message };
let base64Inline = (d.message && d.message.base64) || msg.base64 || null;
let origem = 'direta';

// Cartão de contato (útil para lista de freelancers)
if (msg.contactMessage) {
  texto = `Contato compartilhado: ${msg.contactMessage.displayName || ''}\n${msg.contactMessage.vcard || ''}`;
}
if (msg.contactsArrayMessage) {
  texto = 'Contatos compartilhados:\n' + (msg.contactsArrayMessage.contacts || [])
    .map(c => `${c.displayName || ''}\n${c.vcard || ''}`).join('\n');
}

if (midia) {
  texto = midia.node.caption || texto;
} else {
  // Texto respondendo (citando) uma mídia que o próprio usuário mandou:
  // guarda a mídia citada usando o texto como descrição.
  const ctx = (msg.extendedTextMessage && msg.extendedTextMessage.contextInfo) || {};
  if (ctx.quotedMessage && ctx.stanzaId) {
    const q = unwrap(ctx.quotedMessage);
    const qm = midiaDe(q);
    const autor = String(ctx.participant || '');
    const doUsuario = !autor || autor === d.key.remoteJid || autor.startsWith(phone);
    if (qm && qm.tipo !== 'voz' && doUsuario) {
      midia = qm;
      mediaKey = { key: { id: ctx.stanzaId, remoteJid: d.key.remoteJid, fromMe: false }, message: ctx.quotedMessage };
      base64Inline = null;
      origem = 'citada';
    }
  }
}

if (!texto && !midia) return []; // reação, figurinha, localização etc.

return [{
  json: {
    phone,
    instance: body.instance,
    pushName: d.pushName || '',
    messageId: d.key.id,
    tipo: midia ? midia.tipo : 'texto',
    texto: String(texto || '').trim(),
    mime: midia ? (midia.node.mimetype || null) : null,
    fileName: midia ? (midia.node.fileName || null) : null,
    tamanho: midia ? tamanhoDe(midia.node.fileLength) : null,
    mediaKey: midia ? mediaKey : null,
    base64Inline: midia ? base64Inline : null,
    origem,
  },
}];

// Confere se o número está em authorized_users (ativo).
// Aceita o número com e sem o 9º dígito (WhatsApp às vezes manda sem).
const it = $input.first().json;
const SB = $env.SUPABASE_URL;
const SK = $env.SUPABASE_SERVICE_KEY;
const sbH = { apikey: SK, Authorization: `Bearer ${SK}` };

const p = it.phone;
const variantes = [p];
if (p.startsWith('55') && p.length === 12) variantes.push(p.slice(0, 4) + '9' + p.slice(4));
if (p.startsWith('55') && p.length === 13 && p[4] === '9') variantes.push(p.slice(0, 4) + p.slice(5));

const users = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SB}/rest/v1/authorized_users?phone=in.(${variantes.join(',')})&active=eq.true&select=name,role`,
  headers: sbH,
  json: true,
});

if (!Array.isArray(users) || users.length === 0) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${$env.EVOLUTION_API_URL}/message/sendText/${it.instance}`,
    headers: { apikey: $env.EVOLUTION_API_KEY, 'Content-Type': 'application/json' },
    body: { number: it.phone, text: 'Oi, não reconheço seu número aqui. Fala com o Amano para liberar seu acesso. 👋' },
    json: true,
  });
  return [];
}

return [{ json: { ...it, userName: users[0].name, userRole: users[0].role } }];

// Baixa a mídia (foto, vídeo, PDF, áudio) da Evolution API.
// Áudio de voz (gravado na hora) vira texto via Whisper e é tratado como pedido.
const it = { ...$input.first().json };
if (it.tipo === 'texto') return [{ json: it }];

const EXT = {
  'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
  'video/mp4': 'mp4', 'video/quicktime': 'mov', 'video/3gpp': '3gp',
  'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'aac',
  'application/pdf': 'pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'application/msword': 'doc', 'application/vnd.ms-excel': 'xls',
  'application/zip': 'zip', 'text/plain': 'txt', 'text/csv': 'csv',
};

try {
  let b64 = it.base64Inline;
  let mime = it.mime;
  let fileName = it.fileName;

  if (!b64) {
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${$env.EVOLUTION_API_URL}/chat/getBase64FromMediaMessage/${it.instance}`,
      headers: { apikey: $env.EVOLUTION_API_KEY, 'Content-Type': 'application/json' },
      body: { message: it.mediaKey, convertToMp4: false },
      json: true,
      timeout: 120000,
    });
    b64 = r && r.base64;
    mime = mime || (r && r.mimetype);
    fileName = fileName || (r && r.fileName);
  }
  if (!b64) throw new Error('a Evolution API não devolveu o arquivo');

  b64 = String(b64).replace(/^data:[^;]+;base64,/, '');
  mime = String(mime || 'application/octet-stream').split(';')[0].trim().toLowerCase();
  const ext = EXT[mime] || (fileName && fileName.includes('.') ? fileName.split('.').pop() : 'bin');
  const stamp = new Date().toISOString().slice(0, 19).replace(/[-:T]/g, '');

  it.base64 = b64;
  it.mime = mime;
  it.ext = ext;
  it.tamanho = Math.floor(b64.length * 3 / 4);
  it.fileName = fileName || `${it.tipo}-${stamp}.${ext}`;

  if (it.tipo === 'voz') {
    const boundary = '----nestor' + Date.now();
    const pre = Buffer.from(
      `--${boundary}\r\nContent-Disposition: form-data; name="model"\r\n\r\nwhisper-1\r\n` +
      `--${boundary}\r\nContent-Disposition: form-data; name="language"\r\n\r\npt\r\n` +
      `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="audio.${ext}"\r\nContent-Type: ${mime}\r\n\r\n`
    );
    const post = Buffer.from(`\r\n--${boundary}--\r\n`);
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/audio/transcriptions',
      headers: {
        Authorization: `Bearer ${$env.OPENAI_API_KEY}`,
        'Content-Type': `multipart/form-data; boundary=${boundary}`,
      },
      body: Buffer.concat([pre, Buffer.from(b64, 'base64'), post]),
      timeout: 120000,
    });
    const parsed = typeof res === 'string' ? JSON.parse(res) : res;
    it.texto = String(parsed.text || '').trim();
    it.transcrito = true;
    it.tipo = 'texto';
    delete it.base64;
    if (!it.texto) it.erro = 'Não consegui entender o áudio. Pode mandar de novo ou escrever?';
  }
} catch (e) {
  it.erro = `Não consegui baixar o arquivo (${e.message}). Tenta mandar de novo.`;
}

delete it.base64Inline;
delete it.mediaKey;
return [{ json: it }];

// Claude lê a mensagem (e a imagem/PDF, se houver) e decide a ação:
// SALVAR, BUSCAR, LISTAR, EDITAR, APAGAR, AJUDA ou CONVERSA.
const it = { ...$input.first().json };
if (it.erro) return [{ json: it }];

const SB = $env.SUPABASE_URL;
const SK = $env.SUPABASE_SERVICE_KEY;
const sbH = { apikey: SK, Authorization: `Bearer ${SK}` };

const SYSTEM = `Você é o NESTOR, secretário e memória técnica da Neostore Soluções para Eventos.
Recebe mensagens de WhatsApp (texto, áudio transcrito, fotos, vídeos, PDFs, contatos e outros arquivos) e decide o que fazer chamando a ferramenta "decidir".

AÇÕES
- SALVAR: a mensagem traz informação ou arquivo para guardar (medidas, resoluções, modelos, especificações, contatos, listas, manuais, fotos, vídeos, etiquetas...). Toda mídia recebida sem pedido explícito é SALVAR. Texto afirmativo com dado útil ("totem LG 55 tem 1,80 x 0,60") é SALVAR.
- BUSCAR: pergunta ou pedido de algo guardado ("me manda", "qual a medida", "tem o manual", "quem é o freela de som", "me manda o #12").
- LISTAR: pedido para ver o que existe ("o que tem salvo", "quais categorias", "lista os totens").
- EDITAR: corrigir, renomear, mudar categoria, acrescentar informação ou tornar privado/público um item já salvo. Preencha "codigo" se o usuário citar o número (#12); se disser "o último", "isso", deixe vazio. Preencha SOMENTE os campos que mudam.
- APAGAR: pedido explícito para apagar/excluir. Preencha "codigo" só se o número foi citado.
- AJUDA: pergunta como usar o NESTOR.
- CONVERSA: cumprimento ou assunto fora do escopo. Preencha "resposta" curta, informal e profissional.

COMO PREENCHER (SALVAR)
- titulo: curto e fácil de buscar, com marca/modelo/medida quando houver. Ex.: "Totem touch 43\\" — medidas", "Etiqueta Zebra 100x50 mm", "Freelancers — técnicos de som".
- categoria: minúscula, sem acento. Prefira: totens, tvs, tablets, monitores, projetores, etiquetas, impressoras, freelancers, fornecedores, contatos, manuais, montagem, eventos, logistica, geral. Crie outra só se nenhuma servir.
- tags: 3 a 8 termos de busca (marca, modelo, polegadas, resolução, sinônimos).
- descricao: 1 a 3 frases dizendo o que é. Em imagens, descreva o que aparece e transcreva textos/números visíveis (medidas, etiquetas, códigos, plaquetas).
- conteudo_extraido: em PDFs e imagens com texto, extraia o conteúdo útil (especificações, medidas, procedimentos) de forma fiel. Em texto puro, deixe vazio.
- dados: pares chave-valor objetivos quando houver, unidade no nome da chave. Ex.: {"altura_cm":180,"largura_cm":60,"polegadas":43,"resolucao":"1920x1080","marca":"LG","modelo":"43UH5"}.
- visibilidade: "admin" se o usuário pedir (privado, só pra mim) OU se houver dados pessoais/sensíveis (telefone, CPF, PIX, endereço, valores, cachê). Senão "equipe".

BUSCAR: preencha "consulta" com uma frase de busca completa e autossuficiente, resolvendo referências ao histórico (ex.: "e a do de 55?" → "medidas totem 55 polegadas").
LISTAR: preencha "filtro_categoria" se o usuário citar uma categoria.

Nunca invente dados que não estão na mensagem ou no arquivo.`;

const TOOL = {
  name: 'decidir',
  description: 'Registra a ação a executar e os campos extraídos da mensagem.',
  input_schema: {
    type: 'object',
    properties: {
      acao: { type: 'string', enum: ['SALVAR', 'BUSCAR', 'LISTAR', 'EDITAR', 'APAGAR', 'AJUDA', 'CONVERSA'] },
      titulo: { type: 'string' },
      categoria: { type: 'string' },
      tags: { type: 'array', items: { type: 'string' } },
      descricao: { type: 'string' },
      conteudo_extraido: { type: 'string' },
      dados: { type: 'object' },
      visibilidade: { type: 'string', enum: ['equipe', 'admin'] },
      consulta: { type: 'string' },
      filtro_categoria: { type: 'string' },
      codigo: { type: 'integer' },
      resposta: { type: 'string' },
    },
    required: ['acao'],
  },
};

try {
  const [hist, ultimos] = await Promise.all([
    this.helpers.httpRequest({
      method: 'GET',
      url: `${SB}/rest/v1/conversation_history?phone=eq.${it.phone}&order=created_at.desc&limit=6&select=role,content`,
      headers: sbH, json: true,
    }),
    this.helpers.httpRequest({
      method: 'GET',
      url: `${SB}/rest/v1/nestor_memoria?criado_por=eq.${it.phone}&order=criado_em.desc&limit=3&select=codigo,titulo,categoria`,
      headers: sbH, json: true,
    }),
  ]);

  const historico = (hist || []).reverse()
    .map(h => `${h.role === 'user' ? 'Usuário' : 'Nestor'}: ${String(h.content).slice(0, 400)}`).join('\n');
  const recentes = (ultimos || []).map(u => `#${u.codigo} ${u.titulo} (${u.categoria})`).join('\n');

  const content = [];
  const MB = 1024 * 1024;
  if (it.tipo === 'imagem' && ['image/jpeg', 'image/png', 'image/gif', 'image/webp'].includes(it.mime) && it.tamanho <= 4.5 * MB) {
    content.push({ type: 'image', source: { type: 'base64', media_type: it.mime, data: it.base64 } });
  }
  if (it.tipo === 'documento' && it.mime === 'application/pdf' && it.tamanho <= 20 * MB) {
    content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: it.base64 } });
  }

  const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const arquivo = it.tipo === 'texto' ? 'nenhum'
    : `${it.tipo} — ${it.fileName} (${it.mime}, ${(it.tamanho / MB).toFixed(1)} MB)${content.length ? ' [anexado acima]' : ' [conteúdo não visível, use o nome e a legenda]'}`;

  content.push({
    type: 'text',
    text: `Data/hora: ${agora}
Remetente: ${it.userName} (${it.userRole})
Arquivo: ${arquivo}
Mensagem${it.transcrito ? ' (áudio transcrito)' : ''}: ${it.texto ? `"${it.texto}"` : '(sem texto)'}

Histórico recente:
${historico || '(vazio)'}

Últimos itens salvos por este usuário:
${recentes || '(nenhum)'}`,
  });

  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': $env.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json',
    },
    body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 8000,
      system: SYSTEM,
      tools: [TOOL],
      tool_choice: { type: 'tool', name: 'decidir' },
      messages: [{ role: 'user', content }],
    },
    json: true,
    timeout: 180000,
  });

  const tu = (res.content || []).find(c => c.type === 'tool_use');
  if (!tu) throw new Error('Claude não retornou decisão');
  it.decisao = tu.input;
} catch (e) {
  const detalhe = (e.response && e.response.body && JSON.stringify(e.response.body).slice(0, 200)) || e.message;
  it.erro = `Tive um problema para entender a mensagem (${detalhe}). Tenta de novo em instantes.`;
}

return [{ json: it }];

// Executa a ação decidida pelo Claude e monta a resposta (texto + arquivos a enviar).
const it = { ...$input.first().json };
const helpers = this.helpers;

const SB = $env.SUPABASE_URL;
const SK = $env.SUPABASE_SERVICE_KEY;
const sbH = { apikey: SK, Authorization: `Bearer ${SK}` };
const BUCKET = 'nestor-arquivos';
const LIMITE_ARQUIVO = 50 * 1024 * 1024; // mesmo limite do bucket

const d = it.decisao || {};
const admin = it.userRole === 'admin';
it.resposta = '';
it.midias = [];

const http = (o) => helpers.httpRequest({ json: true, timeout: 120000, ...o });
const ICONE = { texto: '📝', imagem: '🖼️', video: '🎬', documento: '📄', audio: '🎵' };

const AJUDA = `*NESTOR — Secretário Neostore* 🗂️

*Guardar:* mande texto, foto, vídeo, PDF ou contato.
Ex.: "Totem 43 touch: 1,80 x 0,60 m, tela 1920x1080"

*Buscar:* "me manda o manual do projetor Epson" · "qual a medida da etiqueta Zebra?"

*Listar:* "o que tem salvo?" · "lista os totens"

*Corrigir:* "renomeia o #12 para ..." · "muda o último para tvs" · "deixa o #12 privado"

*Apagar:* "apaga o #12"

Dica: responda (citando) uma foto/arquivo seu com a descrição que eu guardo com o contexto certo.`;

function slug(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'geral';
}

function textoParaEmbedding(x) {
  return [
    x.titulo, x.categoria, (x.tags || []).join(', '), x.descricao, x.conteudo,
    x.dados && Object.keys(x.dados).length ? JSON.stringify(x.dados) : '',
  ].filter(Boolean).join('\n').slice(0, 24000);
}

async function embed(texto) {
  const r = await http({
    method: 'POST',
    url: 'https://api.openai.com/v1/embeddings',
    headers: { Authorization: `Bearer ${$env.OPENAI_API_KEY}`, 'Content-Type': 'application/json' },
    body: { model: 'text-embedding-3-small', input: texto || '-' },
  });
  return r.data[0].embedding;
}

async function claude(system, tool, texto) {
  const r = await http({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
    body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 2000,
      system,
      tools: [tool],
      tool_choice: { type: 'tool', name: tool.name },
      messages: [{ role: 'user', content: texto }],
    },
    timeout: 180000,
  });
  const tu = (r.content || []).find(c => c.type === 'tool_use');
  return tu ? tu.input : {};
}

async function buscarItem(codigo) {
  let url = `${SB}/rest/v1/nestor_memoria?select=id,codigo,titulo,categoria,tags,descricao,conteudo,dados,visibilidade,arquivo_path`;
  url += codigo ? `&codigo=eq.${Number(codigo)}` : `&criado_por=eq.${it.phone}&order=criado_em.desc&limit=1`;
  const rows = await http({ method: 'GET', url, headers: sbH });
  return rows && rows[0];
}

async function linkAssinado(path) {
  const r = await http({
    method: 'POST',
    url: `${SB}/storage/v1/object/sign/${BUCKET}/${path}`,
    headers: { ...sbH, 'Content-Type': 'application/json' },
    body: { expiresIn: 3600 },
  });
  const s = r.signedURL || r.signedUrl;
  return s.startsWith('http') ? s : `${SB}/storage/v1${s}`;
}

function mediatypeDe(tipo) {
  if (tipo === 'imagem') return 'image';
  if (tipo === 'video') return 'video';
  return 'document';
}

function etiqueta(row) {
  return `#${row.codigo} ${row.titulo}`;
}

try {
  if (it.erro) throw Object.assign(new Error(it.erro), { jaFormatado: true });

  const acao = d.acao || 'AJUDA';
  if (['SALVAR', 'EDITAR', 'APAGAR'].includes(acao) && !admin) {
    it.resposta = 'Guardar, editar e apagar é só com o Amano. Posso te ajudar a *buscar* algo — é só pedir.';
  }

  // ---------------------------------------------------------- SALVAR
  else if (acao === 'SALVAR') {
    if (it.base64 && it.tamanho > LIMITE_ARQUIVO) {
      it.resposta = `⚠️ Arquivo grande demais (${(it.tamanho / 1048576).toFixed(0)} MB). O limite é 50 MB. Manda um link (Drive/YouTube) que eu guardo o link.`;
    } else {
      const categoria = slug(d.categoria || 'geral');
      let path = null;
      if (it.base64) {
        const nome = slug(String(it.fileName).replace(/\.[^.]+$/, ''));
        path = `${categoria}/${new Date().toISOString().slice(0, 7)}/${Date.now()}-${nome}.${it.ext}`;
        await helpers.httpRequest({
          method: 'POST',
          url: `${SB}/storage/v1/object/${BUCKET}/${path}`,
          headers: { ...sbH, 'Content-Type': it.mime, 'x-upsert': 'true' },
          body: Buffer.from(it.base64, 'base64'),
          timeout: 300000,
        });
      }
      const reg = {
        titulo: d.titulo || it.fileName || String(it.texto).slice(0, 60) || 'Sem título',
        categoria,
        tags: (d.tags || []).map(t => String(t).toLowerCase()),
        descricao: d.descricao || null,
        conteudo: [it.texto, d.conteudo_extraido].filter(Boolean).join('\n\n') || null,
        dados: d.dados || {},
        tipo: it.tipo === 'voz' ? 'audio' : it.tipo,
        arquivo_path: path,
        arquivo_nome: path ? it.fileName : null,
        arquivo_mime: path ? it.mime : null,
        arquivo_tamanho: path ? it.tamanho : null,
        visibilidade: d.visibilidade === 'admin' ? 'admin' : 'equipe',
        criado_por: it.phone,
      };
      reg.embedding = await embed(textoParaEmbedding(reg));
      const rows = await http({
        method: 'POST',
        url: `${SB}/rest/v1/nestor_memoria?select=codigo`,
        headers: { ...sbH, 'Content-Type': 'application/json', Prefer: 'return=representation' },
        body: reg,
      });
      const codigo = rows[0].codigo;
      const linhas = [
        `✅ Guardado *#${codigo}* — ${reg.titulo}`,
        `📁 ${reg.categoria}${reg.tags.length ? ' · 🏷️ ' + reg.tags.slice(0, 5).join(', ') : ''}`,
      ];
      const dadosTxt = Object.entries(reg.dados).slice(0, 6).map(([k, v]) => `${k}: ${typeof v === 'object' ? JSON.stringify(v) : v}`);
      if (dadosTxt.length) linhas.push(`📐 ${dadosTxt.join(' · ')}`);
      if (reg.visibilidade === 'admin') linhas.push('🔒 Privado (só admin)');
      linhas.push(`_Pra corrigir: "renomeia o #${codigo} para ..."_`);
      it.resposta = linhas.join('\n');
    }
  }

  // ---------------------------------------------------------- BUSCAR
  else if (acao === 'BUSCAR' && /#\d+/.test(it.texto)) {
    // Pedido direto por número: "me manda o #12 e o #15"
    const codigos = Array.from(new Set((it.texto.match(/#(\d+)/g) || []).map(s => Number(s.slice(1))))).slice(0, 10);
    const rows = await http({
      method: 'GET',
      url: `${SB}/rest/v1/nestor_memoria?codigo=in.(${codigos.join(',')})${admin ? '' : '&visibilidade=eq.equipe'}` +
           '&select=codigo,titulo,descricao,conteudo,dados,tipo,arquivo_path,arquivo_nome,arquivo_mime',
      headers: sbH,
    });
    if (!rows.length) {
      it.resposta = `Não achei ${codigos.map(c => '#' + c).join(', ')}.`;
    } else {
      it.resposta = rows.map(r => {
        const partes = [`*${etiqueta(r)}*`];
        if (r.descricao) partes.push(r.descricao);
        if (r.dados && Object.keys(r.dados).length) partes.push(Object.entries(r.dados).map(([k, v]) => `${k}: ${typeof v === 'object' ? JSON.stringify(v) : v}`).join(' · '));
        if (!r.arquivo_path && r.conteudo) partes.push(String(r.conteudo).slice(0, 1500));
        return partes.join('\n');
      }).join('\n\n');
      for (const r of rows.filter(x => x.arquivo_path)) {
        it.midias.push({
          url: await linkAssinado(r.arquivo_path),
          mediatype: mediatypeDe(r.tipo),
          mimetype: r.arquivo_mime,
          fileName: r.arquivo_nome,
          caption: etiqueta(r),
        });
      }
    }
  }

  else if (acao === 'BUSCAR') {
    const consulta = d.consulta || it.texto;
    const embedding = await embed(consulta);
    const cands = await http({
      method: 'POST',
      url: `${SB}/rest/v1/rpc/buscar_memoria`,
      headers: { ...sbH, 'Content-Type': 'application/json' },
      body: { p_consulta: consulta, p_embedding: embedding, p_incluir_admin: admin, p_limite: 8 },
    });

    if (!cands || cands.length === 0) {
      it.resposta = `Não achei nada sobre "${consulta}" na memória. Se tiver a informação, me manda que eu guardo.`;
    } else {
      const lista = cands.map(c => [
        `#${c.codigo} | ${c.titulo} | categoria: ${c.categoria} | tipo: ${c.tipo}${c.arquivo_path ? ' | TEM ARQUIVO: ' + c.arquivo_nome : ''}`,
        c.descricao ? `descrição: ${c.descricao}` : '',
        c.dados && Object.keys(c.dados).length ? `dados: ${JSON.stringify(c.dados)}` : '',
        c.conteudo ? `conteúdo: ${String(c.conteudo).slice(0, 1500)}` : '',
      ].filter(Boolean).join('\n')).join('\n\n---\n\n');

      const out = await claude(
        `Você é o NESTOR, secretário da Neostore. Responda ao pedido do usuário pelo WhatsApp usando SOMENTE os itens encontrados na memória.
Regras:
- Curto e direto. Negrito com *um asterisco*. Sem markdown de títulos.
- Traga os dados exatos (medidas, resoluções, modelos, contatos) e cite o #código de cada item usado.
- Ignore itens que não respondem ao pedido. Se nenhum responde, diga que não encontrou.
- Em "enviar_codigos" coloque os códigos dos itens cujo ARQUIVO deve ser enviado: só os relevantes que têm arquivo, no máximo 5 (mais só se o usuário pedir "todos").
- Nunca invente.`,
        {
          name: 'responder',
          description: 'Resposta final para o usuário.',
          input_schema: {
            type: 'object',
            properties: {
              resposta: { type: 'string' },
              enviar_codigos: { type: 'array', items: { type: 'integer' } },
            },
            required: ['resposta', 'enviar_codigos'],
          },
        },
        `Pedido: "${it.texto}"\n\nItens encontrados:\n\n${lista}`,
      );

      it.resposta = out.resposta || 'Não encontrei.';
      const codigos = (out.enviar_codigos || []).slice(0, 10);
      for (const c of cands.filter(x => codigos.includes(Number(x.codigo)) && x.arquivo_path)) {
        it.midias.push({
          url: await linkAssinado(c.arquivo_path),
          mediatype: mediatypeDe(c.tipo),
          mimetype: c.arquivo_mime,
          fileName: c.arquivo_nome,
          caption: etiqueta(c),
        });
      }
    }
  }

  // ---------------------------------------------------------- LISTAR
  else if (acao === 'LISTAR') {
    const vis = admin ? '' : '&visibilidade=eq.equipe';
    if (d.filtro_categoria) {
      const cat = slug(d.filtro_categoria);
      const rows = await http({
        method: 'GET',
        url: `${SB}/rest/v1/nestor_memoria?categoria=eq.${encodeURIComponent(cat)}${vis}&select=codigo,titulo,tipo,visibilidade&order=criado_em.desc&limit=40`,
        headers: sbH,
      });
      it.resposta = rows.length
        ? `*${cat}* (${rows.length}${rows.length === 40 ? '+' : ''})\n` +
          rows.map(r => `${ICONE[r.tipo] || '•'} #${r.codigo} ${r.titulo}${r.visibilidade === 'admin' ? ' 🔒' : ''}`).join('\n') +
          '\n\n_Peça "me manda o #N" para receber._'
        : `Não tem nada em *${cat}* ainda.`;
    } else {
      const cats = await http({
        method: 'POST',
        url: `${SB}/rest/v1/rpc/resumo_categorias`,
        headers: { ...sbH, 'Content-Type': 'application/json' },
        body: { p_incluir_admin: admin },
      });
      const total = cats.reduce((s, c) => s + Number(c.total), 0);
      it.resposta = cats.length
        ? `*Memória do NESTOR* — ${total} itens\n` + cats.map(c => `📁 ${c.categoria}: ${c.total}`).join('\n') +
          '\n\n_Ex.: "lista os totens"_'
        : 'A memória ainda está vazia. Me manda a primeira informação!';
    }
  }

  // ---------------------------------------------------------- EDITAR
  else if (acao === 'EDITAR') {
    const row = await buscarItem(d.codigo);
    if (!row) {
      it.resposta = d.codigo ? `Não achei o #${d.codigo}.` : 'Não achei nenhum item seu para editar. Me diz o número (ex.: #12).';
    } else {
      const patch = {};
      if (d.titulo) patch.titulo = d.titulo;
      if (d.categoria) patch.categoria = slug(d.categoria);
      if (d.tags && d.tags.length) patch.tags = Array.from(new Set([...(row.tags || []), ...d.tags.map(t => String(t).toLowerCase())]));
      if (d.descricao) patch.descricao = d.descricao;
      if (d.visibilidade) patch.visibilidade = d.visibilidade;
      if (d.dados && Object.keys(d.dados).length) patch.dados = { ...(row.dados || {}), ...d.dados };
      if (d.conteudo_extraido) patch.conteudo = [row.conteudo, d.conteudo_extraido].filter(Boolean).join('\n\n');

      if (Object.keys(patch).length === 0) {
        it.resposta = `O que você quer mudar no #${row.codigo} (${row.titulo})? Título, categoria, descrição ou privacidade?`;
      } else {
        const novo = { ...row, ...patch };
        patch.embedding = await embed(textoParaEmbedding(novo));
        await http({
          method: 'PATCH',
          url: `${SB}/rest/v1/nestor_memoria?codigo=eq.${row.codigo}`,
          headers: { ...sbH, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
          body: patch,
        });
        delete patch.embedding;
        const mudou = Object.keys(patch).map(k => k === 'visibilidade' ? (patch[k] === 'admin' ? 'agora privado 🔒' : 'agora visível pra equipe') : k);
        it.resposta = `✏️ Atualizado *#${row.codigo}* — ${novo.titulo}\n(${mudou.join(', ')})`;
      }
    }
  }

  // ---------------------------------------------------------- APAGAR
  else if (acao === 'APAGAR') {
    if (!d.codigo) {
      it.resposta = 'Pra apagar, me diz o número do item. Ex.: "apaga o #12".';
    } else {
      const row = await buscarItem(d.codigo);
      if (!row) {
        it.resposta = `Não achei o #${d.codigo}.`;
      } else {
        if (row.arquivo_path) {
          await http({
            method: 'DELETE',
            url: `${SB}/storage/v1/object/${BUCKET}`,
            headers: { ...sbH, 'Content-Type': 'application/json' },
            body: { prefixes: [row.arquivo_path] },
          });
        }
        await http({
          method: 'DELETE',
          url: `${SB}/rest/v1/nestor_memoria?codigo=eq.${row.codigo}`,
          headers: { ...sbH, Prefer: 'return=minimal' },
        });
        it.resposta = `🗑️ Apagado *#${row.codigo}* — ${row.titulo}`;
      }
    }
  }

  // ---------------------------------------------------------- AJUDA / CONVERSA
  else if (acao === 'AJUDA') {
    it.resposta = AJUDA;
  } else {
    it.resposta = d.resposta || AJUDA;
  }
} catch (e) {
  if (e.jaFormatado) {
    it.erro = e.message;
  } else {
    const detalhe = (e.response && e.response.body && JSON.stringify(e.response.body).slice(0, 200)) || e.message;
    it.erro = `Deu erro ao executar (${d.acao || '?'}): ${detalhe}`;
  }
}

// Não carrega o arquivo para os próximos nós (economiza memória do N8N)
delete it.base64;
return [{ json: it }];

// Envia a resposta e os arquivos pelo WhatsApp e registra histórico + auditoria.
const it = $input.first().json;
const SB = $env.SUPABASE_URL;
const SK = $env.SUPABASE_SERVICE_KEY;
const sbH = { apikey: SK, Authorization: `Bearer ${SK}`, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
const EVO = $env.EVOLUTION_API_URL;
const evoH = { apikey: $env.EVOLUTION_API_KEY, 'Content-Type': 'application/json' };

const texto = it.erro ? `⚠️ ${it.erro}` : (it.resposta || 'Feito.');
const falhas = [];

await this.helpers.httpRequest({
  method: 'POST',
  url: `${EVO}/message/sendText/${it.instance}`,
  headers: evoH,
  body: { number: it.phone, text: texto },
  json: true,
});

for (const m of (it.midias || [])) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${EVO}/message/sendMedia/${it.instance}`,
      headers: evoH,
      body: {
        number: it.phone,
        mediatype: m.mediatype,
        mimetype: m.mimetype,
        caption: m.caption,
        fileName: m.fileName,
        media: m.url,
      },
      json: true,
      timeout: 300000,
    });
  } catch (e) {
    falhas.push(m.caption);
  }
}

if (falhas.length) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${EVO}/message/sendText/${it.instance}`,
    headers: evoH,
    body: { number: it.phone, text: `⚠️ Não consegui enviar: ${falhas.join(', ')}. Tenta pedir de novo.` },
    json: true,
  });
}

// Histórico e auditoria — falha aqui não deve travar a resposta
const entrada = it.tipo === 'texto' ? it.texto : `[${it.tipo}: ${it.fileName || ''}] ${it.texto || ''}`.trim();
const acao = (it.decisao && it.decisao.acao) || 'ERRO';
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SB}/rest/v1/conversation_history`,
    headers: sbH,
    body: [
      { phone: it.phone, role: 'user', content: entrada || '(vazio)' },
      { phone: it.phone, role: 'assistant', content: texto },
    ],
    json: true,
  });
  await this.helpers.httpRequest({
    method: 'POST',
    url: `${SB}/rest/v1/audit_log`,
    headers: sbH,
    body: { phone: it.phone, intent: `SECRETARIO_${acao}`, input: entrada || '(vazio)', output: texto },
    json: true,
  });
} catch (e) {
  // ignora
}

return [{ json: { ok: !it.erro, acao, enviados: (it.midias || []).length - falhas.length } }];
